from typing import Dict, List, Tuple


class Gradebook:
    def __init__(self) -> None:
        # assignment_name -> (weight, kind)
        self._assignments: Dict[str, Tuple[float, str]] = {}
        # student_name -> {assignment_name: grade}
        self._grades: Dict[str, Dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self._assignments[name] = (float(weight), kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"Grade {grade} is outside the valid scale of 2.0 to 5.0.")

        if student not in self._grades:
            self._grades[student] = {}
        self._grades[student][assignment] = float(grade)

    def average(self, student: str) -> float:
        if not self._assignments:
            return 0.0

        student_grades = self._grades.get(student, {})

        # Collect quizzes to determine if the lowest should be dropped
        quizzes: List[Tuple[float, float, str]] = []  # (effective_grade, weight, name)
        homeworks: List[Tuple[float, float]] = []     # (effective_grade, weight)

        for name, (weight, kind) in self._assignments.items():
            # If not recorded, assignment counts as 2.0
            grade = student_grades.get(name, 2.0)
            if kind == "quiz":
                quizzes.append((grade, weight, name))
            else:
                homeworks.append((grade, weight))

        # If student has more than one quiz, drop the one with the lowest grade
        if len(quizzes) > 1:
            # Sort by grade ascending; drop the first element
            quizzes.sort(key=lambda item: item[0])
            active_quizzes = quizzes[1:]
        else:
            active_quizzes = quizzes

        total_weighted_points = sum(grade * weight for grade, weight in homeworks)
        total_weighted_points += sum(grade * weight for grade, weight, _ in active_quizzes)

        total_weight = sum(weight for _, weight in homeworks)
        total_weight += sum(weight for _, weight, _ in active_quizzes)

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_points / total_weight, 2)
```

